import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

class PythagoreanTriplet {

    private final int a;
    private final int b;
    private final int c;

    PythagoreanTriplet(int a, int b, int c) {
        this.a = a;
        this.b = b;
        this.c = c;
    }

    static TripletListBuilder makeTripletsList() {
        return new TripletListBuilder();
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof PythagoreanTriplet)) {
            return false;
        }
        PythagoreanTriplet other = (PythagoreanTriplet) o;
        return a == other.a && b == other.b && c == other.c;
    }

    @Override
    public int hashCode() {
        return 31 * (31 * a + b) + c;
    }

    static class TripletListBuilder {

        private int sum;
        private int maxFactor = Integer.MAX_VALUE;

        TripletListBuilder thatSumTo(int sum) {
            this.sum = sum;
            return this;
        }

        TripletListBuilder withFactorsLessThanOrEqualTo(int maxFactor) {
            this.maxFactor = maxFactor;
            return this;
        }

        List<PythagoreanTriplet> build() {
            List<PythagoreanTriplet> triplets = new ArrayList<>();
            // Euclid's formula: every Pythagorean triplet is a multiple of a
            // primitive triplet generated by coprime m > n of opposite parity.
            for (int m = 2; m * (m + 1) <= sum; m++) {
                for (int n = (m % 2 == 0 ? 1 : 2); n < m; n += 2) {
                    int a = m * m - n * n;
                    int b = 2 * m * n;
                    int c = m * m + n * n;
                    int primitiveSum = a + b + c;
                    if (primitiveSum > sum || sum % primitiveSum != 0) {
                        continue;
                    }
                    int k = sum / primitiveSum;
                    int ka = k * a;
                    int kb = k * b;
                    int kc = k * c;
                    if (kc <= maxFactor) {
                        int x = Math.min(ka, kb);
                        int y = Math.max(ka, kb);
                        triplets.add(new PythagoreanTriplet(x, y, kc));
                    }
                }
            }
            triplets.sort(Comparator.comparingInt((PythagoreanTriplet t) -> t.a)
                    .thenComparingInt(t -> t.b)
                    .thenComparingInt(t -> t.c));
            return triplets;
        }

    }

}

